ORDER.extend(_CARD_FIELDS)
for _language in DATA:
    DATA[_language].extend(_CARD_TEXT[_language].split('|'))

for _language, _values in DATA.items():
    assert len(_values) == len(ORDER), (_language, len(_values))


def install(catalogues):
    """Add the mobile texts under each catalogue (desktop entries win).

    Some desktop catalogues are read-only maps loaded from JSON on demand;
    those get a ChainMap layer instead of being modified."""
    from collections import ChainMap
    for language, values in DATA.items():
        mobile = dict(zip(ORDER, values))
        existing = catalogues.get(language)
        if isinstance(existing, dict):
            for english, text in mobile.items():
                existing.setdefault(english, text)
        elif existing is None:
            catalogues[language] = mobile
        else:
            catalogues[language] = ChainMap(existing, mobile)
